import{_ as t,o as a,c as i,ag as n}from"./chunks/framework.4yUrvjMt.js";const m=JSON.parse('{"title":"ADR-002: Immutable Execution Context","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/decisions/ADR-002-immutable-context.md","filePath":"architecture/decisions/ADR-002-immutable-context.md"}'),o={name:"architecture/decisions/ADR-002-immutable-context.md"};function s(c,e,r,l,d,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-002-immutable-execution-context" tabindex="-1">ADR-002: Immutable Execution Context <a class="header-anchor" href="#adr-002-immutable-execution-context" aria-label="Permalink to &quot;ADR-002: Immutable Execution Context&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2024-01-01</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Shared mutable state is the primary source of subtle bugs in multi-step pipelines. If steps can mutate a shared context object, state management becomes unpredictable and pipelines become hard to test in isolation.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><code>ExecutionContext</code> is immutable. Steps receive a context and return a new context. Mutation is impossible at the type level — all properties are <code>readonly</code> and the object is frozen at runtime via <code>Object.freeze</code>.</p><p>Context updates use pure functions:</p><ul><li><code>withMessages(ctx, messages)</code> — appends messages</li><li><code>withState(ctx, state)</code> — merges state</li><li><code>withDepth(ctx)</code> — increments execution depth</li></ul><p>The pipeline runner applies these functions after each step and threads the updated context forward.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Each step is independently testable with explicit inputs</li><li>No race conditions in async pipelines</li><li>Context changes are explicit and traceable</li><li>Time-travel debugging: any intermediate context can be replayed</li></ul><p><strong>Negative:</strong></p><ul><li>Object allocation on every step (shallow copies via spread)</li><li>Developers new to functional patterns may find this unfamiliar</li></ul>',14)])])}const h=t(o,[["render",s]]);export{m as __pageData,h as default};
